{
  "items": [
    {
      "name": "Polynomial.exists_partition_polynomial_aux",
      "module_name": "Mathlib.NumberTheory.ClassNumber.AdmissibleCardPowDegree",
      "kind": "theorem",
      "type": "∀ {Fq : Type u_1} [inst : Fintype Fq] [inst_1 : Field Fq] (n : ℕ) {ε : ℝ},\n  0 < ε →\n    ∀ {b : Polynomial Fq},\n      b ≠ 0 →\n        ∀ (A : Fin n → Polynomial Fq),\n          ∃ t,\n            ∀ (i₀ i₁ : Fin n),\n              t i₀ = t i₁ ↔ ↑(Polynomial.cardPowDegree (A i₁ % b - A i₀ % b)) < Polynomial.cardPowDegree b • ε"
    },
    {
      "name": "Polynomial.natDegree_pos_iff_degree_pos",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Definitions",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {p : Polynomial R}, 0 < p.natDegree ↔ 0 < p.degree"
    },
    {
      "name": "Ordnode.balancedSz_down",
      "module_name": "Mathlib.Data.Ordmap.Invariants",
      "kind": "theorem",
      "type": "∀ {l r₁ r₂ : ℕ}, r₁ ≤ r₂ → l + r₂ ≤ 1 ∨ l ≤ Ordnode.delta * r₁ → Ordnode.BalancedSz l r₂ → Ordnode.BalancedSz l r₁"
    },
    {
      "name": "Polynomial.degree_lt_degree",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Operations",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {p q : Polynomial R}, p.natDegree < q.natDegree → p.degree < q.degree"
    },
    {
      "name": "Polynomial.natDegree_le_natDegree",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Definitions",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : Semiring R] {p : Polynomial R} [inst_1 : Semiring S] {q : Polynomial S},\n  p.degree ≤ q.degree → p.natDegree ≤ q.natDegree"
    },
    {
      "name": "Polynomial.natDegree_lt_natDegree",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Operations",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : Semiring R] [inst_1 : Semiring S] {p : Polynomial R} {q : Polynomial S},\n  p ≠ 0 → p.degree < q.degree → p.natDegree < q.natDegree"
    },
    {
      "name": "Ordnode.balancedSz_up",
      "module_name": "Mathlib.Data.Ordmap.Invariants",
      "kind": "theorem",
      "type": "∀ {l r₁ r₂ : ℕ}, r₁ ≤ r₂ → l + r₂ ≤ 1 ∨ r₂ ≤ Ordnode.delta * l → Ordnode.BalancedSz l r₁ → Ordnode.BalancedSz l r₂"
    },
    {
      "name": "Polynomial.natDegree_le_of_dvd",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Domain",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] [NoZeroDivisors R] {p q : Polynomial R}, p ∣ q → q ≠ 0 → p.natDegree ≤ q.natDegree"
    }
  ]
}
